#include <bits/stdc++.h>
using namespace std;

void apply_op(vector<int>& p, int x, int y) {
    int n = p.size();
    // [0..x-1] [x..n-y-1] [n-y..n-1] -> [n-y..n-1] [x..n-y-1] [0..x-1]
    vector<int> np;
    for (int i = n - y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n - y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d", &n);
    vector<int> p(n);
    for (int i = 0; i < n; i++) scanf("%d", &p[i]);

    vector<pair<int,int>> ops;

    for (int i = 0; i < n - 2 && (int)ops.size() < 4 * n - 2; i++) {
        int j = -1;
        for (int k = i; k < n; k++) if (p[k] == i + 1) { j = k; break; }
        if (j == i) continue;

        // Need to bring p[j] to position i.
        // Step 1: bring p[j] to position 0 if j > 0 and j < n-1
        // Use op x=j, y=1: swaps prefix[0..j-1] with suffix[n-1], but we want p[j] at front
        // Actually: x=1, y=n-j: takes p[0] and p[j..n-1], swaps them -> [p[j..n-1] | p[1..j-1] | p[0]]
        // That puts p[j] at position 0!

        if (j > 0) {
            int y_val = n - j;
            int x_val = 1;
            if (x_val + y_val < n) {
                ops.push_back({x_val, y_val});
                apply_op(p, x_val, y_val);
            } else {
                // j == 1, so x=1, y=n-1, x+y=n not < n
                // Use x=j, y=1 instead: [p[0..j-1] | p[j..n-2] | p[n-1]] -> [p[n-1] | p[j..n-2] | p[0..j-1]]
                // p[j] is now at position 1... not ideal. Let's try x=2, y=n-2 if n>3
                // Actually for j=1: x=1, y=n-2: [p[0] | p[1] | p[2..n-1]] -> [p[2..n-1] | p[1] | p[0]]
                // p[1] stays at position n-2. Hmm. Let me just use x=j, y=n-j-1 (keep p[j] in middle start)
                ops.push_back({j, 1});
                apply_op(p, j, 1);
                j = find(p.begin(), p.end(), i+1) - p.begin();
                if (j == i) continue;
                if (j > 0 && 1 + (n - j) < n) { ops.push_back({1, n-j}); apply_op(p, 1, n-j); }
            }
        }
        // Now p[0] should be i+1 (if i==0 we're done)
        if (i > 0 && p[0] == i + 1) {
            // op x=i, y=n-i-1: [p[0..i-1]|p[i]|p[i+1..n-1]] -> [p[i+1..n-1]|p[i]|p[0..i-1]]
            // Hmm that doesn't help. Use x=n-i, y=i: [p[0..n-i-1]|nothing?|p[n-i..n-1]] 
            // We want: move p[0] to position i. Use x=1, y=n-1-i.
            if (1 + (n-1-i) < n) { ops.push_back({1, n-1-i}); apply_op(p, 1, n-1-i); }
        }
    }

    printf("%d\n", (int)ops.size());
    for (auto& [a, b] : ops) printf("%d %d\n", a, b);
}
